export default {
  methods: {
    isCombinationKey(event: any) {
      const key = event.altKey;

      return Boolean(key);
    },

    getCombinationKey(event: any) {
      if (!event) {
        return 'alt';
      }
      const key = event.altKey;
      if (key) {
        return 'alt';
      }

      return '';
    },

    getAddRowKeyCodes() {
      const enter_codes = [107, 187];
      return enter_codes;
    },

    isCtrlKey(event: any) {
      const key = event.ctrlKey;

      return Boolean(key);
    },

    isMetaKey(event: any) {
      const key = event.metaKey;

      return Boolean(key);
    },
  },
};
